import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"2025.5.14 Magisk v29.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/29000.md","filePath":"releases/29000.md","lastUpdated":1792939073000}`),a={name:`releases/29000.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="_2025-5-14-magisk-v29-0" tabindex="-1">2025.5.14 Magisk v29.0 <a class="header-anchor" href="#_2025-5-14-magisk-v29-0" aria-label="Permalink to “2025.5.14 Magisk v29.0”">​</a></h1><p>这个版本表面上看起来变化不大，但整个代码库经历了大规模重构和迁移。Magisk 的原生代码以前主要是 C++，但自 2022 年 4 月以来，多位贡献者和作者一直在逐步用 Rust 重写部分代码。经过多年努力，项目的 Rust 化逐渐加速；截至此版本发布时，超过 40% 的原生代码已用 Rust 重写，还有若干主要子系统的重写已在 PR 队列中，计划在下一个版本合并。</p><p>引入新语言的原因并不是为了减少内存安全问题（虽然这是附带好处），而是为了用更现代的编程语言开发 Magisk。</p><ul><li>[General] 大规模内部重构和代码迁移</li><li>[App] 支持下载使用 XZ 压缩的模块 zip 文件</li><li>[App] 当系统动画被禁用时禁用应用动画</li><li>[MagiskMount] 支持使用空白文件节点，通过模块以 systemless 方式删除文件</li><li>[MagiskInit] 重新设计 sepolicy 修补和注入逻辑</li><li>[MagiskSU] 更好的 TTY/PTY 支持</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Massive internal refactoring and code migration</li><li>[App] Support downloading module zip files with XZ compression</li><li>[App] Disable app animations when system animations are disabled</li><li>[MagiskMount] Support systemlessly deleting files with modules using blank file nodes</li><li>[MagiskInit] Redesign sepolicy patching and injection logic</li><li>[MagiskSU] Better TTY/PTY support</li></ul></details><p><strong>完整更新日志： <a href="/MagiskChineseDocument/changes.html">这里</a></strong></p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};